import { useEffect, useSyncExternalStore } from 'react';
import { NormalizedAnime } from '@/types/anime';
import { POSTER_PLACEHOLDER, canonicalAgeRating, canonicalSeason, canonicalSource, canonicalType } from '@/lib/api/normalize';

/**
 * Static catalog index generated by `scripts/build-catalog-index.mjs` from GET /recent-anime.
 * It is served as same-origin static files, so loading it costs the Anikoto API nothing.
 * Chunks load with bounded concurrency, only when search/Explore need them, and a failed run keeps
 * whatever already loaded; retry fetches only the missing chunks.
 */

const SUPPORTED_SCHEMA = 1;
const CHUNK_CONCURRENCY = 3;
const FETCH_TIMEOUT_MS = 20_000;
const CHUNK_ATTEMPTS = 2;
export const INDEX_STALE_AFTER_DAYS = 14;

interface Manifest {
  schemaVersion: number;
  generatedAt: string;
  apiReportedTotal: number;
  recordCount: number;
  complete: boolean;
  posterBase: string;
  chunks: { file: string; count: number }[];
}

interface CompactRecord {
  id: number;
  t: string;
  a?: string;
  s?: string;
  n?: string;
  p?: string;
  ty?: string;
  g?: string[];
  y?: number;
  se?: string;
  st?: string;
  sc?: number;
  ep?: number;
  r?: string;
  sub?: number;
  dub?: number;
  so?: string;
  mal?: string;
  ai?: string;
  ad?: string;
  d?: string;
  up?: string;
}

export type IndexStatus = 'idle' | 'loading' | 'ready' | 'error';

export interface CatalogIndexState {
  status: IndexStatus;
  items: NormalizedAnime[];
  loadedChunks: number;
  totalChunks: number;
  /** Titles in the loaded chunks (excludes live extras). */
  indexedCount: number;
  /** Total the API reported when the index was generated. */
  catalogTotal?: number;
  generatedAt?: string;
  /** True only when every chunk is loaded AND the generator verified it collected every title the API reported. */
  complete: boolean;
  stale: boolean;
  error: string | null;
}

const INITIAL: CatalogIndexState = {
  status: 'idle',
  items: [],
  loadedChunks: 0,
  totalChunks: 0,
  indexedCount: 0,
  complete: false,
  stale: false,
  error: null,
};

let manifest: Manifest | null = null;
const chunkItems = new Map<number, NormalizedAnime[]>();
const liveExtras = new Map<string, NormalizedAnime>();
let status: IndexStatus = 'idle';
let errorMessage: string | null = null;
let inflight: Promise<void> | null = null;
let snapshot: CatalogIndexState = INITIAL;
const listeners = new Set<() => void>();

function expand(c: CompactRecord, m: Manifest): NormalizedAnime {
  const poster = c.p ? (/^https?:/.test(c.p) ? c.p : m.posterBase + c.p) : POSTER_PLACEHOLDER;
  return {
    id: String(c.id),
    rawId: c.id,
    title: c.t || 'Untitled Anime',
    alternativeTitle: c.a,
    synonyms: c.s,
    nativeTitle: c.n,
    synopsis: '',
    posterUrl: poster,
    genres: c.g ?? [],
    type: canonicalType(c.ty),
    status: c.st || 'Unknown',
    releaseYear: c.y,
    aired: c.ad,
    season: canonicalSeason(c.se),
    duration: c.d,
    score: c.sc,
    scoreFormatted: c.sc ? c.sc.toFixed(2) : undefined,
    ageRating: canonicalAgeRating(c.r),
    episodeCount: c.ep,
    isSubCount: c.sub ?? 0,
    isDubCount: c.dub ?? 0,
    hasSub: (c.sub ?? 0) > 0,
    hasDub: (c.dub ?? 0) > 0,
    source: canonicalSource(c.so),
    malId: c.mal,
    aniId: c.ai,
    studios: [],
    producers: [],
    updatedAt: c.up,
  };
}

function rebuild() {
  const indexed: NormalizedAnime[] = [];
  const seen = new Set<string>();
  [...chunkItems.keys()].sort((a, b) => a - b).forEach((k) => {
    for (const item of chunkItems.get(k) ?? []) {
      if (!seen.has(item.id)) {
        seen.add(item.id);
        indexed.push(item);
      }
    }
  });
  // Titles from the live feed that postdate the generated index (matched by id, never invented).
  const extras = [...liveExtras.values()].filter((a) => !seen.has(a.id));
  const total = manifest?.chunks.length ?? 0;
  const generated = manifest ? Date.parse(manifest.generatedAt) : NaN;
  snapshot = {
    status,
    items: extras.length ? [...extras, ...indexed] : indexed,
    loadedChunks: chunkItems.size,
    totalChunks: total,
    indexedCount: indexed.length,
    catalogTotal: manifest?.apiReportedTotal,
    generatedAt: manifest?.generatedAt,
    complete: Boolean(manifest?.complete) && total > 0 && chunkItems.size === total,
    stale: Number.isFinite(generated) && Date.now() - generated > INDEX_STALE_AFTER_DAYS * 86_400_000,
    error: errorMessage,
  };
  listeners.forEach((l) => l());
}

async function fetchJson(url: string, init: RequestInit = {}): Promise<unknown> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(url, { ...init, signal: ctrl.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
    return await res.json();
  } finally {
    clearTimeout(timer);
  }
}

function isManifest(v: unknown): v is Manifest {
  const m = v as Manifest;
  return Boolean(
    m && m.schemaVersion === SUPPORTED_SCHEMA && typeof m.generatedAt === 'string' && Array.isArray(m.chunks) &&
      m.chunks.length > 0 && typeof m.posterBase === 'string' && typeof m.recordCount === 'number'
  );
}

async function loadChunk(index: number, m: Manifest): Promise<void> {
  const file = m.chunks[index].file;
  let lastErr: unknown;
  for (let attempt = 1; attempt <= CHUNK_ATTEMPTS; attempt++) {
    try {
      const data = await fetchJson(`${import.meta.env.BASE_URL}catalog/${file}?v=${encodeURIComponent(m.generatedAt)}`);
      if (!Array.isArray(data)) throw new Error(`Chunk ${file} is not an array`);
      chunkItems.set(
        index,
        (data as CompactRecord[]).filter((r) => r && typeof r.id === 'number').map((r) => expand(r, m))
      );
      rebuild();
      return;
    } catch (e) {
      lastErr = e;
      if (attempt < CHUNK_ATTEMPTS) await new Promise((r) => setTimeout(r, 800 * attempt));
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error('Chunk failed to load');
}

async function run(): Promise<void> {
  status = 'loading';
  errorMessage = null;
  rebuild();
  try {
    if (!manifest) {
      const data = await fetchJson(`${import.meta.env.BASE_URL}catalog/manifest.json`, { cache: 'no-cache' });
      if (!isManifest(data)) throw new Error('The catalog index manifest is missing or has an unsupported version.');
      manifest = data;
      rebuild();
    }
    const m = manifest;
    const pending = m.chunks.map((_, i) => i).filter((i) => !chunkItems.has(i));
    let failure: Error | null = null;
    const workers = Array.from({ length: Math.min(CHUNK_CONCURRENCY, pending.length) }, async () => {
      while (pending.length && !failure) {
        const i = pending.shift() as number;
        try {
          await loadChunk(i, m);
        } catch (e) {
          failure = e instanceof Error ? e : new Error('Chunk failed to load');
        }
      }
    });
    await Promise.all(workers);
    if (failure) throw failure;
    status = 'ready';
    errorMessage = null;
  } catch (e) {
    status = 'error';
    errorMessage = e instanceof Error ? e.message : 'The catalog index could not be loaded.';
  }
  rebuild();
}

/** Starts (or joins) loading. Concurrent callers share one run; already-loaded chunks are never refetched. */
export function ensureIndexLoaded(): Promise<void> {
  if (status === 'ready') return Promise.resolve();
  if (!inflight) {
    inflight = run().finally(() => {
      inflight = null;
    });
  }
  return inflight;
}

export function retryIndex(): Promise<void> {
  if (status === 'loading') return inflight ?? Promise.resolve();
  status = 'idle';
  return ensureIndexLoaded();
}

/** Lets the home feed contribute titles newer than the generated index. */
export function registerLiveItems(items: NormalizedAnime[]): void {
  let changed = false;
  for (const a of items) {
    if (!liveExtras.has(a.id)) {
      liveExtras.set(a.id, a);
      changed = true;
    }
  }
  if (changed) rebuild();
}

const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};
const getSnapshot = () => snapshot;

export function useCatalogIndex({ enabled = true }: { enabled?: boolean } = {}) {
  const state = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  useEffect(() => {
    if (enabled) void ensureIndexLoaded();
  }, [enabled]);
  return { ...state, retry: retryIndex };
}
